command:
$ErrorActionPreference = 'Stop'
$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
if ([string]::IsNullOrWhiteSpace($repo)) { $repo = $env:GITHUB_WORKSPACE }
$branch = 'issue-484-lane-separation-scoring'
$expected = '9fb09e4ccd5f111ae59bc091007ddf4bba56a908'
$remote = ((git -C $repo ls-remote origin ('refs/heads/' + $branch)) -split '\s+')[0]
if ($remote -ne $expected) { throw ('PR head drift: expected ' + $expected + ', got ' + $remote) }
git -C $repo fetch --no-tags origin $branch
if ($LASTEXITCODE -ne 0) { throw 'git fetch failed' }
$worktree = Join-Path $env:RUNNER_TEMP 'issue484-pr501-misleading-nomix-fix'
if (Test-Path $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force }
git -C $repo worktree add --detach $worktree $expected
if ($LASTEXITCODE -ne 0) { throw 'git worktree add failed' }
try {
  $patcher = Join-Path $worktree '_patch_issue484.py'
  @'
from pathlib import Path

source = Path('project_sources/gemini/tools/lib/gemini_behavioral_replay_scoring.py')
validator = Path('project_sources/gemini/tools/validate_gemini_lane_separation_scoring.py')
text = source.read_text(encoding='utf-8')

anchor = '''def _occurrence_has_lane_relation_rejection(text: str, start: int) -> bool:
    prefix = text[max(0, start - 160):start]
    return bool(
        re.search(
            r"\b(?:wrong|incorrect|false|misleading)\s+to\s+(?:say|claim)\b"
            r"[^.!?;]{0,140}$",
            prefix,
        )
    )
'''
addition = anchor + '''

def _occurrence_has_local_lane_relation_rejection(text: str, start: int) -> bool:
    """Reject repudiation frames only within the current comma-delimited discourse segment."""
    prefix = text[max(0, start - 160):start]
    comma = prefix.rfind(",")
    if comma >= 0:
        prefix = prefix[comma + 1:]
    return bool(
        re.search(
            r"\b(?:wrong|incorrect|false|misleading)\s+to\s+(?:say|claim)\b"
            r"[^.!?;]{0,140}$",
            prefix,
        )
    )
'''
if text.count(anchor) != 1:
    raise SystemExit('expected lane rejection helper anchor exactly once')
text = text.replace(anchor, addition, 1)

old = '''    if _find_contextual_term_hits(
        segment,
        [
            "do not mix",
            "don't mix",
            "dont mix",
            "must not mix",
            "should not mix",
            "do not combine",
            "don't combine",
            "dont combine",
            "must not combine",
            "should not combine",
        ],
        skip_negated=True,
        skip_quoted=True,
    ):
        return True
'''
new = '''    for term in (
        "do not mix",
        "don't mix",
        "dont mix",
        "must not mix",
        "should not mix",
        "do not combine",
        "don't combine",
        "dont combine",
        "must not combine",
        "should not combine",
    ):
        for occurrence in _iter_term_occurrences(segment, term):
            if _occurrence_is_quoted(segment, occurrence.start(), occurrence.end()):
                continue
            if _occurrence_is_negated(segment, occurrence.start()):
                continue
            if _occurrence_is_rejected_after(segment, occurrence.end()):
                continue
            if _occurrence_has_local_lane_relation_rejection(
                segment, occurrence.start()
            ):
                continue
            return True
'''
if text.count(old) != 1:
    raise SystemExit('expected no-mix relational branch exactly once')
text = text.replace(old, new, 1)
source.write_text(text, encoding='utf-8')

vtext = validator.read_text(encoding='utf-8')
marker = '    print("Gemini execution-lane separation scoring regressions passed.")\n'
if vtext.count(marker) != 1:
    raise SystemExit('expected validator print marker exactly once')
insert = '''    _expect(
        "It is misleading to say do not mix endpoint response-action syntax and local "
        "workstation PowerShell.",
        False,
        "misleading no-mix rejection",
    )
    _expect(
        "Although it is misleading to say these tools are interchangeable, do not mix "
        "endpoint response-action syntax and local workstation PowerShell.",
        True,
        "comma boundary preserves affirmative no-mix instruction",
    )
'''
if 'misleading no-mix rejection' in vtext:
    raise SystemExit('validator already contains misleading no-mix regression')
vtext = vtext.replace(marker, insert + marker, 1)
validator.write_text(vtext, encoding='utf-8')
'@ | Set-Content -LiteralPath $patcher -Encoding utf8
  Push-Location $worktree
  try {
    python $patcher
    if ($LASTEXITCODE -ne 0) { throw 'patcher failed' }
    Remove-Item -LiteralPath $patcher -Force
    python -m py_compile project_sources/gemini/tools/lib/gemini_behavioral_replay_scoring.py project_sources/gemini/tools/validate_gemini_lane_separation_scoring.py
    if ($LASTEXITCODE -ne 0) { throw 'python syntax validation failed' }
    Push-Location 'project_sources/gemini/tools'
    try {
      python validate_gemini_lane_separation_scoring.py
      if ($LASTEXITCODE -ne 0) { throw 'focused lane-separation validation failed' }
    } finally { Pop-Location }
    $out = Join-Path $env:RUNNER_TEMP 'issue484-pr501-full-replay-validation'
    if (Test-Path $out) { Remove-Item -LiteralPath $out -Recurse -Force }
    python project_sources/gemini/tools/run_gemini_behavioral_replay_validation_suite.py --fixtures-root project_sources/gemini/fixtures/behavioral_replay --output-dir $out
    if ($LASTEXITCODE -ne 0) { throw 'full deterministic Gemini replay validation failed' }
    $changed = @(git diff --name-only)
    $expectedFiles = @('project_sources/gemini/tools/lib/gemini_behavioral_replay_scoring.py','project_sources/gemini/tools/validate_gemini_lane_separation_scoring.py')
    if ($changed.Count -ne 2) { throw ('unexpected changed-file count: ' + ($changed -join ', ')) }
    foreach ($path in $changed) { if ($expectedFiles -notcontains $path) { throw ('unexpected changed file: ' + $path) } }
    git add -- $expectedFiles
    git diff --cached --check
    if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }
    git commit -m 'Bind no-mix rejection to local discourse scope (#484 #506)'
    if ($LASTEXITCODE -ne 0) { throw 'git commit failed' }
    $newHead = (git rev-parse HEAD).Trim()
    git push origin ('HEAD:refs/heads/' + $branch)
    if ($LASTEXITCODE -ne 0) { throw 'git push failed' }
    Write-Host ('PR501_NEW_HEAD=' + $newHead)
    if ((git status --porcelain).Count -ne 0) { throw 'worktree not clean after commit' }
  } finally { Pop-Location }
} finally {
  git -C $repo worktree remove --force $worktree 2>$null
}
